from pathlib import Path
import csv
out=Path(__file__).resolve().parent/'TEST_MATRIX.csv'
rows=[]
def add(area,name,expected,method='Playwright / PHPUnit / container probe',priority='P1'):
 rows.append({'id':f'V8-{len(rows)+1:03d}','area':area,'scenario':name,'expected':expected,'suggested_method':method,'priority':priority,'actual_status':'NOT RUN','evidence_uri':''})
for s in [
('Existing login works','Valid authorized user reaches intended page'),('Invalid credentials','No login; generic inline message'),('Rate limiting after repeated failure','Request throttled; no sensitive detail'),('CSRF protection','Invalid CSRF blocked'),('Session regeneration','Fresh session after login'),('Logout','Session invalidated'),('Valid register','Creates learner role, not admin'),('Duplicate email','Safe error behavior'),('Weak/short password','Server policy enforced'),('Mismatched password','Field-level error and preserved safe text'),('Reset password flow','Expiring one-time token and no enumeration'),('Email verification if active','Prevents unverified access where policy requires'),('Session expiry','Clear reauthentication UX'),('Password manager autofill','Labels and autocomplete correct'),('Password visibility','Toggle with accessible label'),('Form double click','Only one server transaction'),('Network unavailable','No fake success; retry guidance'),('Open redirect in intended URL','Only app-local safe redirect'),('Theme dark/light','Both modes support full auth'),('Mobile 320px','No overflow; input readable'),('Zoom 200%','Controls usable'),('Keyboard navigation','Visible focus and correct ordering'),('Screen-reader error feedback','aria descriptions and alert region'),('Reduced motion','No forced animation')]:add('Auth',*s)
for s in [
('Existing published lesson unchanged','Old content and pinned attempts preserved'),('25 enrichment draft revisions','Each old slug gets revision not overwrite'),('10 new lesson import','New IDs map correctly, data persisted'),('30 new quiz import','Question IDs stable, answers server-only'),('Idempotent content seed','No duplicates on rerun'),('Prerequisite graph','No broken links/cycles'),('Reference source URLs','Official sources, no invented links'),('Reader structured content','Example, fix, limitation, mini-task'),('Review workflow','Staff approval required for publish'),('Unreviewed content','Not exposed to learner'),('Invalid markdown embedded HTML','Rendering sanitized'),('Quiz correct answer secrecy','No answer key in pre-submit response'),('Quiz scoring','Backend checks and explanation returned'),('Question revision pinning','Existing attempts remain consistent'),('Review edit trail','Editor and reviewer audit preserved'),('Catalog query performance','No runaway N+1')]:add('Curriculum',*s)
for id_ in range(9,21):
 add('Lab',f'L{id_:03d} real runtime/response','Local fixture returns real bounded response, no stub')
 add('Lab',f'L{id_:03d} exploit/secure/validation','Own fixture expected different behavior, proof validated backend')
 add('Lab',f'L{id_:03d} reset/idempotency','Reset isolates fixture and repeated submits never reward XP twice')
for s in [
('Lab runner unavailable','Return explicit 503 and no fake solved'),('Lab owner isolation','Cannot inspect another learner session'),('Sandbox network isolation','No core/host/metadata/Internet egress'),('No Docker socket/host mounts','Validated compose/runtime configuration'),('SSRF mock DNS/redirect restrictions','Synthetic allowlist only, blocked route never contacted'),('File upload inertness','No executable path; quarantine only'),('Traversal fixture root','No file outside synthetic fixture root'),('Race lab concurrency budget','Only configured two/three requests; no load testing'),('Old 8 labs regression','All 8 real baseline/proof/reset checks still pass'),('XP consistency','Ledger once per unique solve'),('Reporting integration','Practice report links correct dummy lab and owner')]:add('Lab safety',*s)
for s in [
('Regression MySQL 103+ tests','Current baseline suites do not regress'),('Frontend lint/build','Clean or documented preexisting failures'),('Vitest existing','All prior tests still pass'),('Playwright desktop both themes','Pages visually stable'),('Playwright mobile both themes','No overflow or inaccessible CTAs'),('App readiness checks','Core /up /ready remain intact'),('Backup/restore rehearsal','Snapshot restored in disposable schema only'),('No new open P0/P1','Block release on critical regressions')]:add('Regression',*s)
with out.open('w',encoding='utf-8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
print('QA matrix',len(rows),'cases')
